-- DML: exactly what task execute_compiled_sql of the DAG runs. The base line items go to a temp table,
-- then the output table is truncated and refilled. Reads expense's config table, so load it first:
-- expense/generated_sql/dml/corp_challenger_expense_formula_config.sql.

CREATE TEMP TABLE base_values AS
WITH
Config AS (
  SELECT
    Config_ID,
    TRIM(LineItem) AS LineItem,
    IF((ProfitCentre IS NULL OR TRIM(ProfitCentre) = '' OR UPPER(TRIM(ProfitCentre)) IN ('ALL', 'NA')), 'ALL', TRIM(ProfitCentre)) AS ProfitCentre,
    NULLIF(TRIM(ProfitCentreHierarchyName), '') AS ProfitCentreHierarchyName,
    IF((Account IS NULL OR TRIM(Account) = '' OR UPPER(TRIM(Account)) IN ('ALL', 'NA')), 'ALL', TRIM(Account)) AS Account,
    NULLIF(TRIM(AccountHierarchy), '') AS AccountHierarchy,
    IF((CompanyCode IS NULL OR TRIM(CompanyCode) = '' OR UPPER(TRIM(CompanyCode)) IN ('ALL', 'NA')), 'ALL', TRIM(CompanyCode)) AS CompanyCode,
    IF((CostCenter IS NULL OR TRIM(CostCenter) = '' OR UPPER(TRIM(CostCenter)) IN ('ALL', 'NA')), 'ALL', TRIM(CostCenter)) AS CostCenter,
    IF((Market IS NULL OR TRIM(Market) = '' OR UPPER(TRIM(Market)) IN ('ALL', 'NA')), 'ALL', TRIM(Market)) AS Market,
    IF((DistributionChannel IS NULL OR TRIM(DistributionChannel) = '' OR UPPER(TRIM(DistributionChannel)) IN ('ALL', 'NA')), 'ALL', TRIM(DistributionChannel)) AS DistributionChannel,
    NULLIF(TRIM(DistributionChannelHierarchy), '') AS DistributionChannelHierarchy
  FROM `oddo_project.od_enriched_epmmlops.corp_challenger_expense_formula_config`
  WHERE (Formula IS NULL OR TRIM(Formula) = '')
),
profitcentre_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.ProfitCentre) AS ProfitCentreGranular
  FROM Config C
  LEFT JOIN `oddo_project.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.ProfitCentre = H.parent
    AND H.dimension_name = 'Profit_Center'
    AND (CASE WHEN C.ProfitCentreHierarchyName IS NULL THEN H.is_primary = TRUE ELSE H.hierarchy_name = C.ProfitCentreHierarchyName END)
  WHERE C.ProfitCentre <> 'ALL'
),
account_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.Account) AS AccountGranular
  FROM Config C
  LEFT JOIN `oddo_project.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.Account = H.parent
    AND H.dimension_name = 'Account'
    AND (CASE WHEN C.AccountHierarchy IS NULL THEN H.is_primary = TRUE ELSE H.hierarchy_name = C.AccountHierarchy END)
  WHERE C.Account <> 'ALL'
),
companycode_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.CompanyCode) AS CompanyCodeGranular
  FROM Config C
  LEFT JOIN `oddo_project.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.CompanyCode = H.parent
    AND H.dimension_name = 'Company_Code'
    AND (H.is_primary = TRUE)
  WHERE C.CompanyCode <> 'ALL'
),
costcenter_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.CostCenter) AS CostCenterGranular
  FROM Config C
  LEFT JOIN `oddo_project.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.CostCenter = H.parent
    AND H.dimension_name = 'Cost_Center'
    AND (H.is_primary = TRUE)
  WHERE C.CostCenter <> 'ALL'
),
market_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.Market) AS MarketGranular
  FROM Config C
  LEFT JOIN `oddo_project.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.Market = H.parent
    AND H.dimension_name = 'Market'
    AND (H.is_primary = TRUE)
  WHERE C.Market <> 'ALL'
),
distributionchannel_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.DistributionChannel) AS DistributionChannelGranular
  FROM Config C
  LEFT JOIN `oddo_project.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.DistributionChannel = H.parent
    AND H.dimension_name = 'Distribution_Channel'
    AND (CASE WHEN C.DistributionChannelHierarchy IS NULL THEN H.is_primary = TRUE ELSE H.hierarchy_name = C.DistributionChannelHierarchy END)
  WHERE C.DistributionChannel <> 'ALL'
),
actuals AS (
  SELECT T.year, T.period, T.profit_center, T.Account, T.Company_Code, T.Cost_Center, T.Market, T.Distribution_Channel, SUM(CAST(T.amount AS NUMERIC)) AS amount
  FROM `oddo_project.od_published_epm.epm_p00exp_plan_bdgt_v` T
  INNER JOIN (SELECT DISTINCT ProfitCentreGranular FROM profitcentre_mapping) F_ProfitCentre
    ON F_ProfitCentre.ProfitCentreGranular = T.profit_center
  INNER JOIN (SELECT DISTINCT AccountGranular FROM account_mapping) F_Account
    ON F_Account.AccountGranular = T.Account
  INNER JOIN (SELECT DISTINCT CompanyCodeGranular FROM companycode_mapping) F_CompanyCode
    ON F_CompanyCode.CompanyCodeGranular = T.Company_Code
  INNER JOIN (SELECT DISTINCT CostCenterGranular FROM costcenter_mapping) F_CostCenter
    ON F_CostCenter.CostCenterGranular = T.Cost_Center
  INNER JOIN (SELECT DISTINCT MarketGranular FROM market_mapping) F_Market
    ON F_Market.MarketGranular = T.Market
  INNER JOIN (SELECT DISTINCT DistributionChannelGranular FROM distributionchannel_mapping) F_DistributionChannel
    ON F_DistributionChannel.DistributionChannelGranular = T.Distribution_Channel
  WHERE T.scenario = 'SC.CV'
    AND T.version = 'VR.SUB.8'
    AND T.year IN (
      SELECT FORMAT_DATE('FY%y', DATE_SUB(DATE_ADD(CURRENT_DATE(), INTERVAL 0 MONTH), INTERVAL i YEAR))
      FROM UNNEST(GENERATE_ARRAY(0, 4)) AS i)
  GROUP BY T.year, T.period, T.profit_center, T.Account, T.Company_Code, T.Cost_Center, T.Market, T.Distribution_Channel
),
base_values AS (
  SELECT C.LineItem, A.year AS year, A.period AS month, SUM(A.amount) AS Amount
  FROM actuals A
  INNER JOIN profitcentre_mapping M_ProfitCentre
    ON M_ProfitCentre.ProfitCentreGranular = A.profit_center
  INNER JOIN Config C
    ON C.Config_ID = M_ProfitCentre.Config_ID
  INNER JOIN account_mapping M_Account
    ON M_Account.Config_ID = C.Config_ID
    AND M_Account.AccountGranular = A.Account
  INNER JOIN companycode_mapping M_CompanyCode
    ON M_CompanyCode.Config_ID = C.Config_ID
    AND M_CompanyCode.CompanyCodeGranular = A.Company_Code
  INNER JOIN costcenter_mapping M_CostCenter
    ON M_CostCenter.Config_ID = C.Config_ID
    AND M_CostCenter.CostCenterGranular = A.Cost_Center
  INNER JOIN market_mapping M_Market
    ON M_Market.Config_ID = C.Config_ID
    AND M_Market.MarketGranular = A.Market
  INNER JOIN distributionchannel_mapping M_DistributionChannel
    ON M_DistributionChannel.Config_ID = C.Config_ID
    AND M_DistributionChannel.DistributionChannelGranular = A.Distribution_Channel
  GROUP BY C.LineItem, A.year, A.period
)
SELECT LineItem, year, month, Amount
FROM base_values;

