    SUM(IF(LineItem = 'Calculated Business - Transportation and Logistics Direct Costs WLS', Amount, 0)) - SUM(IF(LineItem = 'Business - Transportation and Logistics Direct Costs WLS', Amount, 0)) AS f_267,
