    SUM(IF(LineItem = 'Calculated Org Other - Digital Content1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Digital Content2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Digital Content3', Amount, 0)) AS f_270,
