    SUM(IF(LineItem = 'Calculated Org Other - Taxes and Penalties1', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Taxes and Penalties2', Amount, 0)) + SUM(IF(LineItem = 'Calculated Org Other - Taxes and Penalties3', Amount, 0)) AS f_295,
